mapper.select:
SELECT
    rfd.*
FROM
    REP_FTP_DETAIL rfd
WHERE
	rfd.PROD_ID = #{prodId, jdbcType=VARCHAR}
	AND rfd.REPORT_NAME = #{reportName, jdbcType=VARCHAR}

		AND rfd.STATR_DATE = #{statrDate, jdbcType=DATE}


		AND rfd.END_DATE = #{endDate, jdbcType=DATE}

	AND rfd.STATUS = 'E'

select
from REP_PROD_INFO R where R.PROD_ID = #{prodId,jdbcType=VARCHAR} and R.REP_PROD_TYPE='03' union select
from V_REP_PROD_INFO V where V.PROD_ID = #{prodId,jdbcType=VARCHAR}

select

from REP_PROD_INFO R
WHERE R.PROD_ID IN(
	SELECT P_PROD_ID FROM REP_PROD_INFO WHERE PROD_ID = #{prodId,jdbcType=VARCHAR}
)
